/** Generated semantic brands for identity-bearing Defold script values. */
export type SemanticHandleKind = "box2d-body" | "box2d-chain" | "box2d-joint" | "box2d-shape" | "box2d-world" | "buffer-data" | "buffer-stream" | "bullet-constraint" | "bullet-object" | "bullet-shape" | "bullet-world" | "graphics-render-target" | "graphics-texture" | "gui-node" | "render-constant-buffer";

declare const semanticHandleBrand: unique symbol;

/** A generation-checked Lua registry root. Disposing it never destroys the engine object. */
export interface DefoldHandle<K extends SemanticHandleKind> {
  readonly runtime: number;
  readonly slot: number;
  readonly generation: number;
  readonly kind: K;
  readonly [semanticHandleBrand]: K;
  dispose(): void;
}

